<template><div class="page-view"><div class="welcome-row"><div><h1>Calendário</h1><p class="subcopy">Prazos conectados automaticamente às tarefas.</p></div></div><div class="calendar-toolbar"><div class="view-switch"><button :class="{active:view==='month'}" @click="view='month'">Mês</button><button :class="{active:view==='week'}" @click="view='week'">Semana</button></div><strong>{{title}}</strong><div><button @click="move(-1)"><ChevronLeft/></button><button @click="today">Hoje</button><button @click="move(1)"><ChevronRight/></button></div></div><div :class="['calendar-complete',{'week-view':view==='week'}]"><section v-for="(day,index) in shownDays" :key="day.toISOString()" :class="['calendar-day',{outside:view==='month'&&day.getMonth()!==cursor.getMonth(),today:isToday(day)}]"><header><small>{{weekdays[index%7]}}</small><strong>{{day.getDate()}}</strong></header><button v-for="task in tasksOn(day)" :key="task.id" class="calendar-task" @click="$emit('task',task)"><strong>{{task.title}}</strong><span>{{project(task.projectId)}}</span></button></section></div></div></template>
<script setup lang="ts">import{computed,ref}from"vue";import{ChevronLeft,ChevronRight}from"lucide-vue-next";import type{Project,Task}from"../stores/taskflow";const props=defineProps<{tasks:Task[];projects:Project[]}>();defineEmits(["task"]);const view=ref<"month"|"week">("month"),cursor=ref(new Date(2026,8,14)),weekdays=["SEG","TER","QUA","QUI","SEX","SÁB","DOM"],title=computed(()=>cursor.value.toLocaleDateString("pt-BR",{month:"long",year:"numeric"}));const monthDays=computed(()=>{const first=new Date(cursor.value.getFullYear(),cursor.value.getMonth(),1),offset=(first.getDay()+6)%7;return Array.from({length:42},(_,i)=>new Date(cursor.value.getFullYear(),cursor.value.getMonth(),i-offset+1))}),weekDays=computed(()=>{const start=new Date(cursor.value);start.setDate(start.getDate()-((start.getDay()+6)%7));return Array.from({length:7},(_,i)=>new Date(start.getFullYear(),start.getMonth(),start.getDate()+i))}),shownDays=computed(()=>view.value==="month"?monthDays.value:weekDays.value);function tasksOn(d:Date){const key=[d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-");return props.tasks.filter(t=>t.due===key)}function move(n:number){const d=new Date(cursor.value);view.value==="month"?d.setMonth(d.getMonth()+n):d.setDate(d.getDate()+n*7);cursor.value=d}function today(){cursor.value=new Date(2026,8,14)}function isToday(d:Date){return d.getFullYear()===2026&&d.getMonth()===8&&d.getDate()===14}const project=(id:number)=>props.projects.find(p=>p.id===id)?.name||"";</script>
